class Solution {
public:
    vector<int> findingUsersActiveMinutes(vector<vector<int>>& logs, int k) {
        unordered_map<int, unordered_set<int>> userMinutes;
        for (const auto& log : logs) {
            userMinutes[log[0]].insert(log[1]);
        }
        vector<int> ans(k, 0);
        for (const auto& [_, minutes] : userMinutes) {
            int count = minutes.size();
            if (count >= 1 && count <= k) {
                ans[count - 1]++;
            }
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int[] findingUsersActiveMinutes(int[][] logs, int k) {
        Map<Integer, Set<Integer>> userMinutes = new HashMap<>();
        for (int[] log : logs) {
            userMinutes.computeIfAbsent(log[0], u -> new HashSet<>()).add(log[1]);
        }
        int[] ans = new int[k];
        for (Set<Integer> minutes : userMinutes.values()) {
            int count = minutes.size();
            if (count >= 1 && count <= k) {
                ans[count - 1]++;
            }
        }
        return ans;
    }
}

/**
 * @param {number[][]} logs
 * @param {number} k
 * @return {number[]}
 */
var findingUsersActiveMinutes = function(logs, k) {
    const userMinutes = new Map();
    for (const [uid, time] of logs) {
        if (!userMinutes.has(uid)) userMinutes.set(uid, new Set());
        userMinutes.get(uid).add(time);
    }
    const ans = Array(k).fill(0);
    for (const minutes of userMinutes.values()) {
        const count = minutes.size;
        if (count >= 1 && count <= k) {
            ans[count - 1]++;
        }
    }
    return ans;
};
